settings.custom_css:
selector .post-items{display:grid!important;grid-template-columns:repeat(3,1fr);gap:24px;margin:0!important}
selector .post-item{width:auto!important;max-width:none!important;flex:none!important;padding:0!important;margin:0!important;display:flex}
selector .elementskit-post-image-card{display:flex;flex-direction:column;width:100%;height:100%;background:#fff!important;border:1px solid #E3E3E3;border-radius:16px;overflow:hidden;box-shadow:none!important}
selector .elementskit-entry-header img{width:100%;aspect-ratio:16/10;object-fit:cover;display:block}
selector .elementskit-post-body{flex:1;display:flex;flex-direction:column;gap:10px;padding:22px 24px 26px!important;background:#fff!important}
selector .post-meta-list{margin:0;padding:0}
selector .meta-date-text{font-family:Barlow,sans-serif;font-size:14px;color:#636363!important}
selector .entry-title{margin:0!important;font-family:'Plus Jakarta Sans',sans-serif;font-size:20px!important;line-height:1.3!important;font-weight:500!important;letter-spacing:-.2px!important;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
selector .entry-title a{color:#161616!important}
selector .btn-wraper{margin-top:auto;padding-top:6px}
selector .elementskit-btn{font-family:Barlow,sans-serif;font-size:15px!important;font-weight:600;color:#073C64!important;padding:0!important;background:transparent!important;border:0!important}
@media(max-width:1024px){selector .post-items{grid-template-columns:repeat(2,1fr)}}
@media(max-width:767px){selector .post-items{grid-template-columns:1fr}}

